properties.query:
let alertWindow = 30m;
let minChunkCount = 10;
let maxChunkSizeBytes = 2000000.0;
let maxReplayWindow = 30m;
let StagingEvents = UAVExfilFlow_CL
    | where TimeGenerated > ago(alertWindow)
    | where StagingDirEvent == true
    | project StageTime = TimeGenerated, UAVId;
let ChunkedFlows = UAVExfilFlow_CL
    | where TimeGenerated > ago(alertWindow)
    | where ChunkCount >= minChunkCount and ChunkSizeBytes > 0 and ChunkSizeBytes < maxChunkSizeBytes;
ChunkedFlows
| join kind=inner (StagingEvents) on UAVId
| where TimeGenerated >= StageTime and TimeGenerated - StageTime <= maxReplayWindow
| summarize arg_max(TimeGenerated, Operator, AssetType, DestIp, DestPort, BytesTransferred, ChunkCount, ChunkSizeBytes, StageTime) by UAVId
| extend TriggerReason = strcat("스테이징후_분할유출_", tostring(ChunkCount), "청크x", tostring(toint(ChunkSizeBytes/1000)), "KB_스테이징후", tostring(datetime_diff('minute', TimeGenerated, StageTime)), "분")
| extend Severity = "High"
| project TimeGenerated, UAVId, Operator, AssetType, DestIp, DestPort, BytesTransferred, ChunkCount, ChunkSizeBytes, StageTime, TriggerReason, Severity
| order by TimeGenerated desc
